from h import *
L=[]
L.append(R(3041,"Kue Angel Nanas","Cita rasa nanas yang menyegarkan berpadu dengan kue angel food yang ringan dalam resep ramah ginjal Kue Angel Nanas ini. Ahli gizi ginjal DaVita, Kim dari Kentucky, mengatakan resepnya yang mudah dibuat ini menjadi makanan penutup atau camilan yang lezat.","12","1/12 kue",
["1 kotak adonan instan kue angel food","20 ons nanas cincang kalengan, dalam sari buah","8 ons Cool Whip® topping makanan penutup beku, sudah dicairkan"],
["Panaskan oven terlebih dahulu hingga 350° F.","Campurkan adonan kue kering dan seluruh isi kaleng nanas beserta sarinya dengan mixer hingga tercampur rata dan mengembang.","Tuang campuran ke dalam loyang kue 9″ x 13″ yang tidak diolesi lemak. Panggang 25 hingga 30 menit hingga bagian atasnya kecokelatan ringan.","Dinginkan sepenuhnya.","Lapisi dengan whipped topping nonsusu. Simpan di lemari es."],
["Untuk kalori lebih tinggi, gunakan nanas dalam sirup kental."],["1 karbohidrat","1/2 buah, rendah kalium","1 tinggi kalori"]))
L.append(R(3043,"Overnight Oats dengan Pir dan Rempah","Persiapan minimal dengan Oat Rempah Pumpkin Pie dengan Pir dari Karol. Campurkan bahan dalam toples, dinginkan di lemari es semalaman, lalu nikmati sebagai sarapan cepat.","1","1 toples",
["1/2 buah pir segar ukuran sedang","1/3 cangkir oat tradisional","2/3 cangkir susu almond vanila tanpa pemanis","1/2 sendok teh bumbu pumpkin pie","1/2 sendok takar bubuk protein whey (opsional)"],
["Potong dadu setengah buah pir.","Campurkan semua bahan dalam toples kaca dan aduk rata. Dinginkan di lemari es semalaman.","Siap disantap keesokan harinya. Anda dapat membawa sarapan Anda bepergian. Pemanasan tidak diperlukan. Tambahkan pemanis jika diinginkan."],
["Siapkan beberapa toples sekaligus untuk sarapan cepat sepanjang minggu.","Jika Anda menginginkan tekstur renyah, gunakan pir segar dan tambahkan di pagi hari. Sebagai pengganti pir segar, Anda dapat menggunakan buah kemasan cangkir berisi pir potong dadu (ditiriskan) atau buah rendah kalium lainnya seperti apel, buah beri, ceri, atau persik.","Perendaman oat semalaman berfungsi sebagai “memasak”. Jika lebih suka oatmeal hangat, panaskan toples dalam microwave selama 1-2 menit sebelum dimakan."],["1 protein (daging)","1 karbohidrat","1 buah, kalium sedang","1 lemak"]))
L.append(R(3044,"Jeruk Bali Madu Panggang","Saat Anda menjalani diet ginjal, resep Jeruk Bali Madu Panggang ini adalah cara yang lezat dan sehat untuk memulai pagi Anda.","2","1/2 jeruk bali",
["1 buah jeruk bali","2 sendok teh madu","1/4 sendok teh kayu manis"],
["Panaskan pemanggang (broiler) terlebih dahulu hingga 400º F.","Belah jeruk bali menjadi dua, lalu potong di sekeliling tepi dan segmen setiap belahan jeruk bali.","Siram bagian atas setiap belahan dengan satu sendok teh madu dan 1/8 sendok teh kayu manis.","Panggang jeruk bali selama 6 menit atau hingga mulai kecokelatan.","Sajikan hangat."],
["Memotong jeruk bali per segmen sebelum dipanggang membuatnya lebih mudah dimakan.","Jeruk bali dan jus jeruk bali diketahui berinteraksi dengan beberapa obat. Konsultasikan dengan tim perawatan kesehatan Anda untuk memastikan jeruk bali aman dimasukkan dalam diet Anda."],["1 buah, kalium sedang"]))
L.append(R(3045,"Sayuran Musim Panas Panggang","Sayuran panggang mengalami karamelisasi di bagian luar sambil tetap empuk di bagian dalam—dengan rasa alami yang tidak memerlukan tambahan garam. Cobalah resep Sayuran Musim Panas Panggang dari Tammi untuk campuran sayuran rendah kalium yang tepat.","6","3/4 cangkir",
["2 lobak ukuran sedang","1 wortel ukuran sedang","4 siung bawang putih","4 sendok teh minyak zaitun","1 sendok teh marjoram kering","1 bawang bombai ukuran sedang","1/2 paprika merah ukuran sedang","1 zucchini kecil","5 jamur putih ukuran sedang","1/4 pon buncis","1/4 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 375° F.","Bilas dan keringkan sayuran. Potong lobak dan wortel menjadi potongan 2 inci; cincang halus bawang putih.","Masukkan lobak, wortel, dan setengah bawang putih cincang ke dalam mangkuk lalu siram dengan 2 sendok teh minyak zaitun. Tambahkan marjoram dan aduk hingga sayuran terlapisi minyak.","Semprot dua loyang dengan semprotan masak antilengket; bagi dan susun sayuran secara merata di atas loyang. Masukkan loyang ke dalam oven selama 30 menit.","Selagi lobak dan wortel dipanggang, potong bawang bombai, paprika merah, dan zucchini menjadi potongan 2 inci dan belah dua jamur. Buang ujung buncis tetapi biarkan tetap utuh. Masukkan sayuran ke dalam mangkuk dan siram dengan 2 sendok teh minyak zaitun. Tambahkan sisa bawang putih dan lada hitam; aduk perlahan hingga sayuran terlapisi minyak.","Setelah lobak dan wortel dipanggang selama 30 menit, angkat loyang dari oven. Bagi campuran sayuran buncis ke dua loyang. Campurkan sayuran dengan lobak dan wortel yang sudah setengah matang, bentuk satu lapisan di atas loyang. Kembalikan ke oven selama 15–20 menit lagi, masak hingga sayuran empuk."],
["Sayuran panggang memiliki rasa ekstra dibandingkan sayuran kukus atau rebus. Tidak perlu garam.","Cobalah berbagai kombinasi sayuran."],["1-1/2 sayuran, kalium sedang","1/2 lemak"]))
L.append(R(3046,"Buncis Gurih","Nikmati resep Buncis Gurih yang lezat dan ramah ginjal.","6","1/2 cangkir",
["1 pon buncis beku potong memanjang gaya Prancis","1 sendok makan minyak","1/2 cangkir bawang bombai","1 siung bawang putih","2 sendok teh daun dill kering","1 sendok makan jus lemon","1 sendok teh saus Worcestershire","1/3 cangkir remah roti plain","2 sendok makan mentega tanpa garam"],
["Panaskan oven terlebih dahulu hingga 400° F.","Cincang bawang bombai dan cincang halus bawang putih.","Masak buncis dalam microwave sesuai petunjuk kemasan.","Dalam wajan sedang, panaskan minyak dan tumis bawang bombai dengan bawang putih hingga bawang bombai bening.","Tambahkan daun dill, jus lemon, dan saus Worcestershire lalu aduk rata.","Tambahkan buncis dan aduk. Letakkan dalam wadah casserole.","Lelehkan mentega dan campurkan dengan remah roti. Taburkan di atas campuran buncis dan panggang selama 5 hingga 10 menit hingga kecokelatan."],
[],["1 sayuran","1 lemak","1/2 karbohidrat"]))
L.append(R(3049,"Asparagus Vinaigrette Anggur Merah","Nikmati resep ramah ginjal Asparagus Vinaigrette Anggur Merah ini pada makan malam akhir pekan Anda berikutnya.","8","1/2 cangkir",
["1 siung bawang putih","2 pon asparagus segar","1 sendok makan minyak zaitun","1/4 cangkir dressing vinaigrette anggur merah","1/2 sendok teh lada hitam"],
["Cincang halus bawang putih; potong asparagus menjadi potongan 2″.","Panaskan minyak dalam wajan, masukkan bawang putih dan tumis selama 1 menit.","Tambahkan potongan asparagus; aduk hingga tercampur.","Tambahkan dressing vinaigrette anggur merah dan lada.","Aduk dan panaskan satu menit lagi.","Angkat dari api dan sajikan."],
["Buat dressing vinaigrette anggur merah Anda sendiri dengan mencampurkan cuka anggur merah dan minyak zaitun dalam jumlah yang sama dengan campuran herbal rendah natrium."],["1 sayuran, kalium sedang","1/2 lemak"]))
L.append(R(3050,"Nasi Limun dengan Sayuran Campur","Nasi Limun dengan Sayuran Campur adalah resep ramah ginjal yang lezat dan mudah dibuat.","6","2/3 cangkir",
["2 sendok makan bawang bombai","12 ons limun","1/2 cangkir air","1 cangkir beras merah, belum dimasak","1 cangkir sayuran campur beku","1/2 sendok teh lada hitam","1/4 sendok teh pala bubuk","1/8 sendok teh garam"],
["Cincang halus bawang bombai.","Tuang limun dan air ke dalam penanak nasi atau panci. Tambahkan beras, bawang bombai, sayuran campur, dan bumbu.","Nyalakan penanak nasi atau masak di atas kompor, tertutup, dengan api sedang selama 20 menit."],
["Limun segar, beku, kemasan botol, atau kalengan dapat digunakan dalam resep ini. Perlu diketahui, beberapa limun mengandung zat tambahan fosfat yang meningkatkan kandungan fosfor. Baca label dan hindari merek dengan zat tambahan ini.","Pilih campuran sayuran dengan wortel, jagung, buncis, kacang polong hijau, atau ganti dengan campuran sayuran beku rendah kalium favorit Anda.","Jika Anda menderita diabetes, cobalah limun bebas gula dalam resep ini untuk menurunkan karbohidrat sebanyak 5 gram per porsi.","Untuk hasil terbaik, jangan buka tutup atau aduk nasi selama memasak."],["1-1/2 karbohidrat","1 sayuran, rendah kalium"]))
L.append(R(3051,"Salad Sayuran Campur","Paprika merah, jus lemon, dan mentimun hanyalah beberapa dari bahan lezat yang menyusun resep ramah ginjal Salad Sayuran Campur.","4","1/2 cangkir",
["1 mentimun ukuran sedang","1 paprika merah manis","1/2 ikat dill segar","3 batang daun bawang","1 sendok makan jus lemon","1/3 cangkir sour cream","1/8 sendok teh lada hitam"],
["Kupas, buang biji, dan potong dadu mentimun dan paprika merah.","Cincang dill dan daun bawang.","Campurkan semua bahan dalam mangkuk saji dan aduk.","Dinginkan setidaknya satu jam sebelum disajikan."],
["Gunakan sour cream rendah lemak jika diinginkan."],["1 sayuran, kalium sedang","1/2 lemak"]))
L.append(R(3052,"Pai Apel Juara Utama","Pai Apel Juara Utama dikirimkan oleh ahli gizi ginjal Barb dari North Carolina. Panggang pai deep-dish yang ramah ginjal ini dan nikmati aromanya yang menyenangkan serta rasanya yang menggoda.","8","1/8 pai",
["4 butir telur besar","1-1/2 cangkir saus apel","3/4 cangkir gula merah padat","3 sendok makan tepung terigu serbaguna putih","1 sendok teh parutan kulit lemon","4 sendok makan jus lemon","1/4 sendok teh garam","1/2 sendok teh kayu manis bubuk","1/4 sendok teh pala bubuk","1 kulit pai deep-dish yang belum dipanggang, ukuran 9”","1 buah apel ukuran sedang","1/4 cangkir selai aprikot"],
["Panaskan oven terlebih dahulu hingga 450° F.","Dalam mangkuk pengaduk besar, campurkan telur, saus apel, gula merah, tepung, parutan kulit lemon, 3 sendok makan jus lemon, garam, kayu manis, dan pala; aduk rata.","Tuang campuran ke dalam kulit pai yang belum dipanggang. Panggang selama 15 menit. Turunkan suhu oven hingga 300° F. Panggang 45 menit lagi atau hingga pisau yang ditusukkan di dekat bagian tengah keluar bersih. Dinginkan sebentar di atas rak kawat.","Selagi pai dipanggang, kupas dan iris tipis apel.","Campurkan irisan apel dan 1 sendok makan jus lemon dalam mangkuk; aduk rata. Tata irisan apel membentuk kincir di atas pai yang sudah dipanggang.","Lelehkan selai dalam panci kecil dengan api kecil, sambil terus diaduk. Olesi irisan apel dengan selai yang sudah meleleh.","Letakkan pai di atas rak loyang pemanggang (broiler). Panggang 6” dari sumber panas selama 3 menit atau hingga apel empuk dan selai berbuih."],
["Pilihan karbohidrat lebih rendah bagi penderita diabetes termasuk menggunakan 1/4 cangkir + 2 sendok makan Splenda® Brown Sugar Blend sebagai pengganti gula merah, dan menggunakan olesan buah aprikot sebagai pengganti selai. Ini mengurangi kalori menjadi 216, karbohidrat 32 g dan 2 pilihan karbohidrat.","Kandungan natrium kulit pai siap pakai bervariasi antarmerek. Pilih merek dengan kandungan natrium terendah atau pertimbangkan membuat kulit pai buatan sendiri dengan garam yang dikurangi."],["1 karbohidrat","1 buah, rendah kalium","1 tinggi kalori","1-1/2 lemak"]))
L.append(R(3053,"Salad Nasi dan Cabai dengan Dressing Vinaigrette Krim","Tambahkan sentuhan pedas ke meja makan dengan resep ramah ginjal ini, Salad Nasi dan Cabai dengan Dressing Vinaigrette Krim.","8","1/2 cangkir",
["1 cangkir beras putih butir panjang, belum dimasak","1/4 sendok teh garam","1 cabai poblano besar","1 cangkir kacang polong beku","1 cangkir mentimun","1/4 cangkir daun bawang","1/4 cangkir kemangi/ketumbar segar (cilantro)","1/2 cangkir paprika merah","1/2 cangkir paprika hijau","1 siung bawang putih","2 sendok makan cuka sari apel","2 sendok makan jus limau segar","1 sendok teh mustard Dijon","1 sendok teh jintan bubuk","1/2 cangkir sour cream","2 sendok makan minyak zaitun","1/4 sendok teh lada hitam"],
["Untuk memasak nasi, didihkan 1-3/4 cangkir air dalam panci 2 liter dan masukkan beras dan garam. Didihkan air lagi, aduk sekali, tutup dan kecilkan api hingga mendidih perlahan selama 15 menit atau hingga air menguap. Angkat dari api dan diamkan, tertutup, setidaknya 10 menit.","Untuk memanggang cabai, letakkan di bawah pemanggang (broiler), balik sesering mungkin hingga gosong merata. Ketika cabai menghitam di semua sisi, pindahkan ke kantong plastik atau mangkuk, tutup dan rapatkan lalu biarkan dingin. Kupas kulit cabai yang gosong, bilas dan keringkan dengan ditepuk-tepuk. Potong dadu cabai.","Cairkan kacang polong; kupas dan buang biji mentimun; cincang mentimun, daun bawang, dan cilantro; potong dadu paprika dan cincang halus bawang putih.","Untuk menyusun salad, campurkan nasi dan cabai potong dadu. Tambahkan kacang polong yang sudah dicairkan, paprika, bawang, mentimun, dan cilantro. Aduk rata hingga tercampur.","Untuk menyiapkan dressing, campurkan semua bahan dressing dan aduk rata.","Aduk dressing dengan campuran nasi dan sayuran. Dinginkan hingga siap disajikan."],
["Cabai poblano juga dikenal sebagai cabai ancho.","Panggang cabai lebih awal agar ada waktu untuk mendingin.","Kenakan sarung tangan karet saat membuang biji dan urat dari cabai pedas.","Untuk tampilan yang menarik, sajikan di atas piring saji yang dialasi daun selada."],["1 sayuran, kalium sedang","1 karbohidrat","1 lemak"]))
L.append(R(3054,"Paprika Hijau Isi Kalkun","Cobalah resep ramah ginjal Paprika Hijau Isi Kalkun ini pada makan malam Anda berikutnya.","8","1 paprika",
["8 paprika hijau besar","2 pon daging kalkun giling","1 cangkir nasi merah matang","1 sendok makan paprika manis Hungaria","1/2 sendok teh garam","1 butir telur","1 bawang bombai ukuran sedang, dicincang halus","3 siung bawang putih ukuran sedang, dicincang halus","1/2 cangkir tomat hancur","1 cangkir kaldu sapi rendah natrium"],
["Panaskan oven terlebih dahulu hingga 350°F.","Buang tangkai paprika dan bersihkan biji serta selaput dari bagian dalam.","Campurkan kalkun, nasi, telur, bawang bombai, bawang putih, dan bumbu hingga rata.","Isi paprika dengan campuran daging.","Letakkan paprika dalam loyang pemanggang besar.","Tuang tomat hancur dan kaldu di atas paprika","Panggang selama 1 jam 15 menit."],
["Gunakan daging dada kalkun giling untuk isian yang paling tanpa lemak, tetapi daging sapi giling tanpa lemak juga merupakan isian yang menyehatkan jantung.","Jika Anda tidak menjalani diet pembatasan kalium, gunakan 1 kaleng tomat hancur 16 ons.","Buat dua kali lipat dan bekukan paprika per porsi untuk hidangan mudah saat Anda tidak ingin memasak.","Paprika isi sangat umum di seluruh Eropa Tengah dan Timur. Bumbu dan jenis daging untuk isiannya bervariasi tidak hanya dari satu wilayah ke wilayah lain, tetapi juga di dalam satu wilayah. Beberapa menggunakan 100% daging sapi giling, dan yang lain menggunakan campuran daging.","Untuk diet protein lebih rendah, Anda dapat menggunakan satu pon kalkun dan menambah nasi menjadi 3 cangkir."],["3 daging","2 sayuran, kalium tinggi"]))
L.append(R(3056,"Agua Fresca Semangka","Air segar yang diblender dengan semangka dan jus limau adalah penghilang dahaga yang sempurna untuk hari musim panas yang terik atau kapan saja. Agua Fresca Semangka rendah kalium sehingga menjadi pilihan yang bagus untuk diet ginjal.","4","1 cangkir",
["2 cangkir semangka, tanpa biji","1/4 cangkir air","1/4 cangkir gula","2 tangkai daun mint","1 buah limau (untuk hiasan)"],
["Potong limau menjadi irisan. Potong semangka menjadi potongan besar dan ukur 2 cangkir.","Masukkan semangka ke dalam blender bersama 2 irisan limau dan blender hingga halus.","Saring campuran dengan saringan dan tuang ke dalam 4 cangkir. Hiasi dengan daun mint dan irisan limau lalu sajikan."],
["Ganti gula dengan pemanis stevia untuk mengurangi karbohidrat menjadi 12 gram."],["1 buah, kalium sedang","1 tinggi kalori"]))
L.append(R(3061,"Camilan “Es Krim” Nonsusu Nanas","Hanya empat bahan dan tanpa memasak membuat Camilan “Es Krim” Nonsusu Nanas ramah anggaran dan mudah dibuat.","18","1 camilan; persegi 2-1/4”",
["1 kaleng nanas cincang 20 ons, ditiriskan dengan baik","4 sendok takar bubuk protein whey vanila","1 wadah whipped topping lite 16 ons","36 keping persegi biskuit graham"],
["Campurkan nanas yang sudah ditiriskan dan bubuk protein hingga rata, lipat whipped topping ke dalamnya.","Letakkan satu lapis biskuit graham persegi di atas loyang kue dan oleskan sekitar 2 sendok makan campuran topping pada setiap biskuit.","Letakkan keping biskuit graham lain di atasnya dan masukkan loyang ke dalam freezer.","Setelah beku dengan baik, bungkus satu per satu dengan plastik pembungkus dan simpan dalam wadah kedap udara di freezer."],
["Beberapa whipped topping mengandung zat tambahan fosfor. Periksa daftar bahan untuk memastikan fosfor tidak ditambahkan.","Satu kotak biskuit graham 14.4 ons berisi sekitar 27 lembar persegi panjang.","Bubuk protein dapat bervariasi dalam kandungan protein, kalium, fosfor, dan natrium. Anda dapat berbicara dengan ahli gizi Anda untuk mengetahui mana yang sesuai bagi Anda."],["1-1/2 karbohidrat"]))
L.append(R(3063,"Buncis Panggang ala Roast","Belum pernah Anda mencicipi sayuran seperti ini! Ahli gizi ginjal DaVita, Brady dari Ohio, menunjukkan cara memanggang buncis agar empuk dan menggoda! Dengan hidangan ini, Anda tidak perlu khawatir membuat anak-anak makan sayuran. Dan hidangan ini juga cocok untuk diet ramah ginjal sehingga Anda bisa yakin semua orang akan meminta tambah Buncis Panggang ala Roast!","4","1 cangkir",
["1 pon buncis segar","1-1/2 sendok makan minyak zaitun","1/4 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 450° F.","Cuci buncis dan potong ujungnya.","Alasi loyang berbibir dengan foil aluminium dan sebarkan buncis di atas foil.","Tuang minyak zaitun di atas buncis dan aduk perlahan hingga buncis terlapisi merata.","Panggang dalam oven selama 10 menit.","Angkat loyang dari oven dan ratakan kembali buncis agar matang merata.","Kembalikan ke oven dan panggang sekitar 10 menit lagi atau hingga buncis memiliki beberapa bagian cokelat keemasan.","Angkat dari oven, bumbui dengan lada bubuk dan sajikan."],
["Untuk rasa ekstra, cobalah minyak beraroma lemon atau herba."],["1 sayuran, kalium sedang","1 lemak"]))
L.append(R(3065,"Roti Kelapa","Kelapa parut dan sour cream memberikan keseimbangan sempurna antara rasa manis dan kelembapan pada Roti Kelapa yang ramah ginjal ini. Tambahkan sedikit nanas untuk mengubahnya menjadi hidangan ala Hawaii.","12","1 iris",
["2 sendok makan minyak kelapa","1/3 cangkir mentega tanpa garam","1/2 cangkir gula","2 butir telur besar","1 cangkir kelapa parut kering manis","1 cangkir sour cream","2 cangkir tepung terigu serbaguna","1 sendok teh soda kue","1-1/2 sendok teh baking powder"],
["Panaskan oven terlebih dahulu hingga 350° F. Olesi loyang roti 9 x 5 inci dengan lemak. Keluarkan mentega agar lunak.","Hangatkan minyak kelapa di microwave hingga baru saja meleleh. Sisihkan hingga dingin.","Kocok mentega dan gula hingga lembut. Tambahkan minyak kelapa dan telur; aduk bersama. Campurkan sour cream. Tambahkan kelapa parut ke dalam campuran dan aduk.","Dalam mangkuk terpisah campurkan tepung, soda kue, dan baking powder.","Lipat bahan kering ke dalam bahan basah. Tuang adonan ke dalam loyang roti.","Panggang 45 hingga 60 menit, hingga roti cokelat keemasan dan tusuk gigi keluar bersih.","Dinginkan roti dalam loyang selama 5 hingga 10 menit lalu keluarkan dari loyang dan dinginkan di atas rak kawat."],
["Jika diinginkan tambahkan 1/2 cangkir nanas potong dadu atau hancur.","Bungkus beberapa iris roti dengan pembungkus freezer dan bekukan untuk camilan cepat nanti."],["1 karbohidrat","1/2 tinggi kalori","1-1/2 lemak"]))
save(4,L)
